create table if not exists public.profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.monthly_finance (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, month date not null, income numeric(14,2), expense numeric(14,2), investable numeric(14,2), cash_savings numeric(14,2), etf_contribution numeric(14,2), emergency_fund numeric(14,2), total_assets numeric(14,2), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, month));
create table if not exists public.research_assets (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, symbol text, name text not null, asset_type text not null, market text, sector text, status text, rating text, valuation_summary text, fundamentals_summary text, risk_summary text, latest_price numeric(14,4), as_of_date date, reference_urls jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, symbol, market));
create table if not exists public.research_notes (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, asset_id bigint references public.research_assets(id) on delete cascade, research_date date not null default current_date, fact text, analysis text, uncertainty text, reference_urls jsonb not null default '[]'::jsonb, conclusion text, created_at timestamptz not null default now());
create table if not exists public.investment_decisions (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, decision_date date not null default current_date, asset_id bigint references public.research_assets(id) on delete set null, symbol text, decision text not null, rationale text, reference_urls jsonb not null default '[]'::jsonb, outcome text, review_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.tasks (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, month date not null, task_key text not null, title text not null, priority text, status text not null default 'todo', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, month, task_key));
create table if not exists public.monthly_reviews (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, month date not null, market_summary text, core_strategy text, buy_list jsonb not null default '[]'::jsonb, watch_list jsonb not null default '[]'::jsonb, avoid_list jsonb not null default '[]'::jsonb, key_lesson text, prior_call_review text, next_month_plan text, reference_urls jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, month));
create table if not exists public.portfolio (id bigint generated by default as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, symbol text not null, name text, asset_type text, quantity numeric(20,6), avg_cost numeric(14,4), current_price numeric(14,4), current_value numeric(18,2), as_of_date date, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, symbol));
create index if not exists idx_monthly_finance_user_month on public.monthly_finance(user_id, month desc);
create index if not exists idx_research_assets_user on public.research_assets(user_id);
create index if not exists idx_research_notes_user_date on public.research_notes(user_id, research_date desc);
create index if not exists idx_decisions_user_date on public.investment_decisions(user_id, decision_date desc);
create index if not exists idx_tasks_user_month on public.tasks(user_id, month);
create index if not exists idx_reviews_user_month on public.monthly_reviews(user_id, month desc);
create index if not exists idx_portfolio_user on public.portfolio(user_id);
alter table public.profiles enable row level security;
alter table public.monthly_finance enable row level security;
alter table public.research_assets enable row level security;
alter table public.research_notes enable row level security;
alter table public.investment_decisions enable row level security;
alter table public.tasks enable row level security;
alter table public.monthly_reviews enable row level security;
alter table public.portfolio enable row level security;
drop policy if exists profiles_select_own on public.profiles; create policy profiles_select_own on public.profiles for select using (auth.uid() = user_id);
drop policy if exists profiles_insert_own on public.profiles; create policy profiles_insert_own on public.profiles for insert with check (auth.uid() = user_id);
drop policy if exists profiles_update_own on public.profiles; create policy profiles_update_own on public.profiles for update using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists monthly_finance_all_own on public.monthly_finance; create policy monthly_finance_all_own on public.monthly_finance for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists research_assets_all_own on public.research_assets; create policy research_assets_all_own on public.research_assets for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists research_notes_all_own on public.research_notes; create policy research_notes_all_own on public.research_notes for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists investment_decisions_all_own on public.investment_decisions; create policy investment_decisions_all_own on public.investment_decisions for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists tasks_all_own on public.tasks; create policy tasks_all_own on public.tasks for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists monthly_reviews_all_own on public.monthly_reviews; create policy monthly_reviews_all_own on public.monthly_reviews for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
drop policy if exists portfolio_all_own on public.portfolio; create policy portfolio_all_own on public.portfolio for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
